  if ((!isDNS()) || (!getInterface()->isPacketInterface()) ||
      (ndpiFlow == NULL))
    return;

  /* Instruct nDPI to continue the dissection
     See
     https://github.com/ntop/ntopng/commit/30f52179d9f7a1eb774534def93d55c77d6070bc#diff-20b1df29540b6de59ceb6c6d2f3afdb5R387
